    a_wins = data['option_a_ratings'].apply(sum)
    b_wins = data['option_b_ratings'].apply(sum)
    mask = b_wins > a_wins
    if mask.sum() == 0:
        return 0.0
    return float(data.loc[mask, 'response'].mean())

